// P0 of the super-agent borrow design (docs/decisions/superagent-borrow-design.md §2, §10, §11): the protocol
// contract and the off baseline, checked without a provider and without a consumer.
//
// Every case comes in the shape the design asks for: the contract refuses what it cannot honour (v1, an owner model,
// a stored policy that disagrees, a migration that has not drained), the off position is HEAD's by object identity and
// by generated bytes. §12 records root-decision-v1; a deployment must still name its intent selection explicitly.
import test from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { cleanupDirs } from '../../packages/profiles/test-support/temp-roots.mjs';
import {
  superagentBorrowConfig, SUPERAGENT_BORROW_DEFAULTS, SUPERAGENT_BORROW_CODES, superagentBorrowCodeList,
  INTENT_SEMANTICS_VALUES, borrowReadiness, assertProtocolSupported, assertBorrowPreconditions, teamPolicyRow,
  policyDecision, assertPolicyCompatible, MIGRATION_PREREQUISITES, migrationCheck, assertMigrationReady,
  ROOT_TOOL_POLICY, TOOL_CAPABILITIES, TOOL_CAPABILITY_DECLARATIONS, capabilityDeclaration, toolCapabilityDecision,
  BORROW_POLICY_VERSION, codes, canonical, digest, hash,
} from '../../packages/contracts/index.mjs';
import { teamSchemas, teamSchemasFor, teamSchemasForBorrow, roleTools } from '../../packages/contracts/team-tools.mjs';
import { generate } from '../../packages/profiles/index.mjs';
import { apply as applyTeamProfile } from '../../packages/profiles/team-plugin.mjs';
import { profile } from '../../packages/host/test-support/profile.mjs';
import { ControlStore } from '../../packages/store/index.mjs';
import { OwnershipHandle, TeamManager, acquireOwnership } from '../../packages/host/index.mjs';

const repo = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const scenario = path.join(repo, 'verification', 'fixtures', 'superagent-borrow-off-scenario.mjs');
const POSITIONS = [['off', 'off'], ['off', 'on'], ['on', 'off'], ['on', 'on']];
const ROLES = ['root', 'subCoordinator', 'worker', 'verifier'];

test('§2: the plugin refuses v1 before it mounts, and refuses to open a store whose policy was written under v1', async () => {
  // Nothing is created before the refusal: apply() throws on a context that has no services at all.
  assert.throws(() => applyTeamProfile({}, { root: path.join(os.tmpdir(), 'borrow-never-created'), superagentBorrow: 'v1',
    autonomy: 'on', collab: 'on' }), error => error?.code === 'PROTOCOL_UNSUPPORTED');

  for (const request of [{ superagentBorrow: 'v1' }, { ownerModel: { provider: 'p', model: 'm' } }]) {
    assert.throws(() => applyTeamProfile({}, request), error => error?.code === 'PROTOCOL_UNSUPPORTED');
  }

  // The reverse direction of §2: an "off" build must not open a library that a v1 build wrote.
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'borrow-policy-'));
  let primary = null;
  try {
    const first = await profile({ root });
    const teamId = first.runtime.core.configuration.teamId;
    assert.equal(typeof teamId, 'string');
    // Written through the same reducer path a later activation would use, so the row carries the store's envelope too.
    first.runtime.core.mutate('team-policy:' + teamId, 'adapter', {}, tx => tx.put('team-policy:' + teamId,
      teamPolicyRow(teamId, { superagentBorrow: 'v1', activatedAt: new Date().toISOString(), migrationRef: 'migration:summary-1' })));
    assert.equal(policyDecision(first.runtime.store.read('team-policy:' + teamId), 'v1').decision, 'match');
    await first.close({ remove: false });
    await assert.rejects(profile({ root }), error => error?.code === 'POLICY_MISMATCH',
      'an off build must not open a library a v1 build wrote');
  } catch (error) {
    primary = error;
    throw error;
  } finally {
    // A refused mount still had the store open for a moment; retry each transient lock and report every failure. A
    // cleanup failure on the success path is a test failure; if the assertion already failed, it stays the primary one.
    const errors = cleanupDirs([root]);
    if (errors.length) {
      const message = 'borrow-policy cleanup errors: ' + errors.map(e => e.dir + ': ' + e.error.message).join('; ');
      if (primary) { primary.cleanupErrors = errors; console.error(message); }
      else throw Object.assign(Error(message), { cleanupErrors: errors });
    }
  }
});

test('§2, §10: omitted and explicit off match HEAD, and a profile mutation is caught', { timeout: 600000 }, () => {
  const baseline = headTree();
  const scratch = fs.mkdtempSync(path.join(os.tmpdir(), 'borrow-off-baseline-'));
  try {
    const baselineScenario = path.join(baseline.tree, 'verification', 'fixtures', 'superagent-borrow-off-scenario.mjs');
    const before = runScenario(baseline.tree, baselineScenario, path.join(scratch, 'head-work'));
    const after = runScenario(repo, scenario, path.join(scratch, 'work'));
    const named = runScenario(repo, scenario, path.join(scratch, 'explicit-work'), 'explicit-off');
    assertOffEquivalent(after, before);
    assertOffEquivalent(named, before);
    // Mutation validation uses the exact comparator used above, against a temporary tree only.
    // Turning off instantInterrupt is an off-mode regression, even if every other legacy test stayed green.
    const source = path.join(baseline.tree, 'packages', 'profiles', 'index.mjs');
    const original = fs.readFileSync(source, 'utf8');
    assert.equal(original.split('instantInterrupt: true').length - 1, 1);
    fs.writeFileSync(source, original.replace('instantInterrupt: true', 'instantInterrupt: false'));
    const mutant = runScenario(baseline.tree, baselineScenario, path.join(scratch, 'mutant-work'));
    assert.throws(() => assertOffEquivalent(after, mutant), /generated profile/,
      'the real golden comparator must kill the executor/latch mutation');
  } finally {
    fs.rmSync(scratch, { recursive: true, force: true });
    fs.rmSync(baseline.dir, { recursive: true, force: true });
  }
});

function assertOffEquivalent(after, before) {
  assert.deepEqual(after.profiles, before.profiles, 'the generated profile, executor and instantInterrupt are HEADs');
  assert.deepEqual(after.positions, before.positions, 'every tool schema and role catalog is HEADs');
  assert.deepEqual(after.contracts.collab, before.contracts.collab);
  assert.deepEqual(after.contracts.autonomy, before.contracts.autonomy);
  const upgraded = structuredClone(before.executions);
  for (const execution of Object.values(upgraded)) execution.snapshots = upgradeResponsibilityPages(execution.snapshots);
  assert.deepEqual(after.executions, upgraded, 'only the explicit multi-responsibility snapshot upgrade differs from HEAD');
  for (const execution of Object.values(after.executions)) {
    assert.equal(execution.teamPolicyRows, 0);
    assert.equal(execution.runtime.teamPolicyRows, 0);
  }
  const added = after.contracts.codes.filter(code => !before.contracts.codes.includes(code)).sort();
  assert.deepEqual(added, [...superagentBorrowCodeList].sort(), 'only the borrow refusal names are new');
  for (const code of before.contracts.codes) assert(after.contracts.codes.includes(code), code + ' must survive');
}

// The product fix intentionally replaces the historical one-item page, even with borrow off. Keep an exact golden
// for every other byte/row/tool; independently assemble just this fixture's known two-item upgrade from HEAD pages.
function upgradeResponsibilityPages(pages) {
  return pages.map((page, index) => {
    const result = structuredClone(page), payload = result.payload;
    const tail = pages.slice(index);
    for (const field of ['responsibilities', 'memberData', 'detailRefs']) payload[field] = tail.flatMap(item => item.payload[field]);
    payload.responsibilityPage = { ...payload.responsibilityPage, nextPage: null, omittedCount: 0 };
    const render = () => '<team_snapshot rev="' + payload.asOfSeq + '" hash="' + digest(payload) + '">\n' +
      canonical(payload).replaceAll('<', '\\u003c').replaceAll('>', '\\u003e') + '\n</team_snapshot>';
    if (Buffer.byteLength(render()) * 2 > 4096 && payload.collab) {
      for (const field of ['responsibilities', 'memberData', 'detailRefs']) payload[field] = page.payload[field];
      payload.responsibilityPage = { ...page.payload.responsibilityPage, omittedCount: pages.length - index - 1 };
      tail.splice(1);
    }
    result.text = render();
    result.manifest = { ...result.manifest, payloadHash: digest(payload), hash: hash(result.text),
      messageIds: tail.flatMap(item => item.manifest.messageIds), detailRefs: payload.detailRefs,
      messageBindings: tail.flatMap(item => item.manifest.messageBindings), accepted: tail.every(item => item.manifest.accepted) };
    return result;
  });
}

// A raw context avoids profile()'s failure cleanup masking a leaked store in the product.
function mountContext() {
  const sessions = new Map();
  return { get(name) { return this[name]; }, provide(name, value) { this[name] = value; }, on() {},
    sessions: { get: id => sessions.get(id), async create(id) { const session = { id }; sessions.set(id, session); return session; } } };
}

test('§2: policy refusal closes the store even when ownership cleanup rejects', async () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'borrow-cleanup-'));
  const first = await profile({ root });
  const teamId = first.runtime.core.configuration.teamId;
  first.runtime.core.mutate('team-policy:' + teamId, 'adapter', {}, tx => tx.put('team-policy:' + teamId,
    teamPolicyRow(teamId, { superagentBorrow: 'v1', activatedAt: new Date().toISOString(), migrationRef: null })));
  await first.close({ remove: false });
  const originalRelease = OwnershipHandle.prototype.release, originalClose = TeamManager.prototype.close;
  let managerClosed = 0, refusedStore;
  const originalRead = ControlStore.prototype.read;
  try {
    ControlStore.prototype.read = function(id) { if (id === 'team-policy:' + teamId) refusedStore = this; return originalRead.call(this, id); };
    OwnershipHandle.prototype.release = async function() { await originalRelease.call(this); throw Error('injected ownership cleanup failure'); };
    TeamManager.prototype.close = async function() { managerClosed++; return originalClose.call(this); };
    const ctx = mountContext();
    applyTeamProfile(ctx, { root });
    await assert.rejects(ctx.teamRuntime.ready, error => error?.code === 'POLICY_MISMATCH' &&
      error.cleanupErrors?.some(failure => /injected/.test(failure.message)));
    assert(refusedStore);
    assert.throws(() => originalRead.call(refusedStore, 'team-policy:' + teamId), /closed|not open/i);
    assert.equal(managerClosed, 1, 'one cleanup rejection must not skip the manager');
  } finally {
    ControlStore.prototype.read = originalRead;
    OwnershipHandle.prototype.release = originalRelease;
    TeamManager.prototype.close = originalClose;
    fs.rmSync(root, { recursive: true, force: true });
  }
});

test('§2: a store constructor failure still releases ownership and manager', async () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'borrow-open-failure-'));
  const originalRelease = OwnershipHandle.prototype.release, originalClose = TeamManager.prototype.close;
  let released = 0, closed = 0;
  try {
    OwnershipHandle.prototype.release = async function() { released++; return originalRelease.call(this); };
    TeamManager.prototype.close = async function() { closed++; return originalClose.call(this); };
    // prepareHost/preflight accept an empty directory. This regular file makes the subsequent mkdir/open fail.
    fs.writeFileSync(path.join(root, 'state-v2'), 'not a directory');
    const ctx = mountContext();
    applyTeamProfile(ctx, { root });
    await assert.rejects(ctx.teamRuntime.ready, /EEXIST|ENOTDIR/);
    assert.equal(released, 1);
    assert.equal(closed, 1);
    const ownership = await acquireOwnership({ root });
    await ownership.release();
  } finally {
    OwnershipHandle.prototype.release = originalRelease;
    TeamManager.prototype.close = originalClose;
    fs.rmSync(root, { recursive: true, force: true });
  }
});

const BASELINE = '5325aeb';

/** A pristine checkout of the committed baseline; the commit is a contract of this test, so its absence is a failure. */
function headTree() {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'borrow-head-baseline-'));
  const archive = path.join(dir, 'head.tar');
  try {
    execFileSync('git', ['cat-file', '-e', BASELINE + '^{commit}'], { cwd: repo, stdio: 'ignore', windowsHide: true });
  } catch (error) {
    throw Error('the baseline commit ' + BASELINE + ' is not in this repository (' + (error.message ?? error) + '); the ' +
      'off comparison needs the committed code, not a description of it');
  }
  execFileSync('git', ['archive', '--format=tar', '-o', archive, BASELINE], { cwd: repo, windowsHide: true });
  const tree = path.join(dir, 'head');
  fs.mkdirSync(tree, { recursive: true });
  // Relative paths and a relative -C, run from the extraction directory: a drive letter in -f is "host:path" to the tar
  // that ships with this platform, and the tree this unpacks is never outside the throwaway directory anyway.
  execFileSync('tar', ['-xf', 'head.tar', '-C', 'head'], { cwd: dir, windowsHide: true });
  // The scenario is the same file on both sides, never a second copy of the expectations.
  const BASELINE_SCENARIO = 'superagent-borrow-off-scenario.mjs';
  // The package directories were renamed after this baseline commit (team-core -> core, control-store -> store): the
  // copy stays the same file, and only its relative import paths are translated to the names that tree carries.
  const BASELINE_PACKAGES = { core: 'team-core', store: 'control-store', 'adapter-dsh': 'dsh-adapter', ui: 'client-team' };
  const baselineScenario = fs.readFileSync(scenario, 'utf8').replace(/\.\.\/\.\.\/packages\/(core|store|adapter-dsh|ui)\//g,
    (whole, name) => '../../packages/' + BASELINE_PACKAGES[name] + '/');
  fs.mkdirSync(path.join(tree, 'verification', 'fixtures'), { recursive: true });
  fs.writeFileSync(path.join(tree, 'verification', 'fixtures', BASELINE_SCENARIO), baselineScenario);
  // packages/delivery resolves its git roots against <repo>/runs at import time and refuses a root that does not exist;
  // an archive carries no ignored directory. The build pointer has to travel too, or generate() would select the default
  // build on a machine where the prepared one is named - a difference in the environment, not in the behaviour.
  fs.mkdirSync(path.join(tree, 'runs'), { recursive: true });
  const pointer = path.join(repo, 'runs', 'm1b-build-current.txt');
  if (fs.existsSync(pointer)) fs.copyFileSync(pointer, path.join(tree, 'runs', 'm1b-build-current.txt'));
  return { dir, tree };
}

/** Run the scenario in one tree over its own work directory and return what it printed. */
function runScenario(tree, scriptPath, work, mode = 'omitted') {
  const out = execFileSync(process.execPath, [scriptPath, work, mode], { cwd: tree, encoding: 'utf8', windowsHide: true,
    maxBuffer: 64 * 1024 * 1024 });
  return JSON.parse(out.trim().split(/\r?\n/).at(-1));
}
